/// Read session paths from a file or stdin (when path is "-").
/// Returns a HashSet of session paths for filtering.
pub(crate) fn read_session_paths(
    source: &str,
) -> Result<std::collections::HashSet<String>, std::io::Error> {
    use std::collections::HashSet;
    use std::io::{BufRead, BufReader};

    let reader: Box<dyn BufRead> = if source == "-" {
        Box::new(BufReader::new(std::io::stdin()))
    } else {
        Box::new(BufReader::new(std::fs::File::open(source)?))
    };

    let mut paths = HashSet::new();
    for line_result in reader.lines() {
        let line = line_result?;
        let trimmed = line.trim();
        if trimmed.is_empty() || trimmed.starts_with('#') {
            continue;
        }
        paths.insert(trimmed.to_string());
    }

    Ok(paths)
}

pub(crate) enum BoundedSessionPaths {
    Complete(std::collections::HashSet<String>),
    TimedOut,
}

pub(crate) fn sessions_from_error(error: impl std::fmt::Display) -> CliError {
    CliError {
        code: 2,
        kind: CliErrorKind::SessionsFrom.kind_str(),
        message: format!("failed to read session paths: {error}"),
        hint: Some("Provide a file path or '-' for stdin".to_string()),
        retryable: false,
    }
}

/// Materialize a session-path scope all-or-nothing behind the caller's robot
/// deadline. The caller never searches against a partially read scope.
pub(crate) fn read_session_paths_bounded(
    source: &str,
    remaining_ms: Option<u64>,
) -> CliResult<BoundedSessionPaths> {
    let Some(remaining_ms) = remaining_ms else {
        return read_session_paths(source)
            .map(BoundedSessionPaths::Complete)
            .map_err(sessions_from_error);
    };
    if remaining_ms == 0 {
        return Ok(BoundedSessionPaths::TimedOut);
    }

    let source = source.to_string();
    let (sender, receiver) = std::sync::mpsc::sync_channel(1);
    std::thread::Builder::new()
        .name("cass-bounded-session-paths".to_string())
        .spawn(move || {
            let _ = sender.send(read_session_paths(&source));
        })
        .map_err(|error| sessions_from_error(format!("could not start reader: {error}")))?;
    match receiver.recv_timeout(Duration::from_millis(remaining_ms)) {
        Ok(result) => result
            .map(BoundedSessionPaths::Complete)
            .map_err(sessions_from_error),
        Err(std::sync::mpsc::RecvTimeoutError::Timeout) => Ok(BoundedSessionPaths::TimedOut),
        Err(std::sync::mpsc::RecvTimeoutError::Disconnected) => {
            Err(sessions_from_error("session-path reader disconnected"))
        }
    }
}

/// GH#414: how many of the requested `--sessions-from` paths the index has
/// actually seen. A filter that resolves to ZERO indexed sessions makes an
/// empty result byte-identical to a genuine miss, and the natural (wrong)
/// recovery is to broaden the query and then doubt the archive — the filter
/// is the one part that looks like it could not have gone wrong.
///
/// Point lookups against `conversations.source_path` (indexed by the schema),
/// bounded by a wall-clock deadline so a pathological million-line filter
/// file can never stall the search it decorates. `None` means "could not
/// determine" (DB missing/busy, deadline exceeded) — callers must render
/// that as unknown, never as zero.
pub(crate) fn count_indexed_session_paths(
    db_path: &Path,
    requested: &std::collections::HashSet<String>,
) -> Option<usize> {
    use crate::franken_sync::compat::RowExt;
    if requested.is_empty() || !db_path.is_file() {
        return None;
    }
    let mut conn =
        crate::storage::sqlite::open_franken_owner_strict_readonly_connection_with_timeout(
            db_path,
            Duration::from_secs(2),
        )
        .ok()?;
    let deadline = std::time::Instant::now() + Duration::from_millis(500);
    let mut matched = 0_usize;
    let mut complete = true;
    for path in requested {
        if std::time::Instant::now() >= deadline {
            complete = false;
            break;
        }
        let exists = conn.query_row_map(
            "SELECT EXISTS(SELECT 1 FROM conversations WHERE source_path = ?1)",
            &[crate::franken_sync::compat::ParamValue::from(path.as_str())],
            |row| row.get_typed::<i64>(0),
        );
        match exists {
            Ok(flag) if flag != 0 => matched += 1,
            Ok(_) => {}
            Err(_) => {
                complete = false;
                break;
            }
        }
    }
    let _ = conn.close_without_checkpoint_sync();
    complete.then_some(matched)
}

/// Workspace paths the archive knows about, through the strict read-only
/// opener. `None` when the database cannot be read quickly.
pub(crate) fn indexed_workspace_paths(db_path: &Path) -> Option<Vec<String>> {
    use crate::franken_sync::compat::RowExt;
    if !db_path.is_file() {
        return None;
    }
    let mut conn =
        crate::storage::sqlite::open_franken_owner_strict_readonly_connection_with_timeout(
            db_path,
            Duration::from_secs(2),
        )
        .ok()?;
    let paths = conn
        .query_map_collect(
            "SELECT path FROM workspaces",
            &[] as &[crate::franken_sync::compat::ParamValue],
            |row| row.get_typed::<String>(0),
        )
        .ok();
    let _ = conn.close_without_checkpoint_sync();
    paths
}

/// uojcg.7.1: a search filtered to one `--workspace` that comes back empty
/// reads exactly like "nothing matches", so an agent drops a query that a
/// moved checkout, a `/Users` vs `/home` path, a trailing slash or a case
/// difference emptied. Check the filter against the indexed workspaces and
/// probe once without it (lexical, one hit), then say which case this is.
/// `None` when either probe cannot run; a probe that misses reports a genuine
/// no-match, never a suggestion.
pub(crate) fn diagnose_empty_workspace_search(
    client: &crate::search::query::SearchClient,
    query: &str,
    filters: &crate::search::query::SearchFilters,
    field_mask: crate::search::query::FieldMask,
    db_path: &Path,
) -> Option<crate::search::zero_result_diagnosis::ZeroResultReport> {
    let mut requested = filters.workspaces.iter();
    let (Some(requested), None) = (requested.next(), requested.next()) else {
        return None;
    };
    let known = indexed_workspace_paths(db_path)?;
    let mut unfiltered = filters.clone();
    unfiltered.workspaces.clear();
    let global_had_hits = !client
        .search(query, unfiltered, 1, 0, field_mask)
        .ok()?
        .is_empty();
    Some(crate::search::zero_result_diagnosis::diagnose_zero_result(
        requested,
        &known,
        global_had_hits,
    ))
}

