pub(crate) fn omp_session_dir_from_path(path: &Path) -> Option<PathBuf> {
    if let Some(root) = crate::connectors::omp::configured_session_root(path) {
        return Some(root);
    }

    if crate::connectors::omp::is_resolved_live_config_session_path(path) {
        return None;
    }

    path.ancestors().find_map(|ancestor| {
        ancestor
            .file_name()
            .is_some_and(|name| name == "sessions")
            .then(|| ancestor.to_path_buf())
    })
}

/// Detect which coding-agent harness owns a given session path.
///
/// Detection is path-based and mirrors the layouts that the bundled
/// connectors understand. If `agent_override` is set, its value is
/// validated and returned verbatim.
pub(crate) fn detect_resume_agent(
    path: &Path,
    agent_override: Option<&str>,
) -> CliResult<DetectedAgent> {
    if let Some(raw) = agent_override {
        let normalized = raw.trim().to_ascii_lowercase();
        let slug = match normalized.as_str() {
            "claude" | "claude_code" | "claude-code" => "claude",
            "codex" => "codex",
            "opencode" => "opencode",
            "pi_agent" | "pi-agent" | "pi" => "pi_agent",
            "omp" | "oh-my-pi" | "ohmypi" | "oh_my_pi" => "omp",
            "gemini" => "gemini",
            // Antigravity resumes via `agy --conversation <uuid>`; `agy` is
            // the binary name, so accept it as an alias for the slug.
            "antigravity" | "agy" => "antigravity",
            other => {
                return Err(CliError {
                    code: 2,
                    kind: CliErrorKind::InvalidAgent.kind_str(),
                    message: format!(
                        "unknown --agent value '{other}'; expected one of: claude, codex, opencode, pi_agent, pi, omp, gemini, antigravity"
                    ),
                    hint: None,
                    retryable: false,
                });
            }
        };
        return Ok(DetectedAgent {
            slug,
            is_override: true,
            reason: format!("--agent override: {raw}"),
        });
    }

    // Normalize separators and ASCII case before applying layout markers.
    // Native Windows paths use `\` on a case-insensitive filesystem, while
    // archived paths may retain the conventions of a different host.
    let path_str = path
        .to_string_lossy()
        .replace('\\', "/")
        .to_ascii_lowercase();
    // Path-substring detection. These match the real on-disk layouts
    // and are ordered longest-match-first where it matters.
    //
    // We deliberately only match Claude Code via `.claude/projects`
    // (the canonical path segment). An earlier draft also matched
    // `claude_code` anywhere in the path, but that produced false
    // positives on user directories named things like
    // `~/projects/my_claude_code_extension/`. Users on unusual installs
    // can always force detection with `--agent claude`.
    if path_str.contains(".claude/projects") {
        return Ok(DetectedAgent {
            slug: "claude",
            is_override: false,
            reason: "path contains .claude/projects".to_string(),
        });
    }
    if path_str.contains(".codex/sessions") || path_str.contains("/codex/sessions") {
        return Ok(DetectedAgent {
            slug: "codex",
            is_override: false,
            reason: "path contains .codex/sessions".to_string(),
        });
    }
    if path_str.contains("opencode.db")
        || path_str.contains(".local/share/opencode")
        || path_str.contains(".config/opencode")
    {
        return Ok(DetectedAgent {
            slug: "opencode",
            is_override: false,
            reason: "path references opencode storage".to_string(),
        });
    }
    if crate::connectors::omp::owns_session_path(path) {
        return Ok(DetectedAgent {
            slug: "omp",
            is_override: false,
            reason: "path matches an OMP v18 session store".to_string(),
        });
    }
    if path_str.contains(".pi/agent") {
        return Ok(DetectedAgent {
            slug: "pi_agent",
            is_override: false,
            reason: "path contains .pi/agent".to_string(),
        });
    }
    // Antigravity stores its transcripts under
    // `~/.gemini/antigravity{,-cli}/brain/<uuid>/.system_generated/logs/transcript.jsonl`
    // (IDE store and `agy` CLI store respectively, #454). Those paths ALSO
    // contain `.gemini/`, so they must be matched BEFORE the gemini arm below
    // or an antigravity session would be misrouted to the Gemini harness.
    // (probe.rs / fleet_archive_coverage.rs enforce the same
    // antigravity-before-gemini ordering.)
    if path_str.contains("/antigravity/")
        || path_str.contains("antigravity-cli")
        || path_str.contains(".system_generated")
    {
        return Ok(DetectedAgent {
            slug: "antigravity",
            is_override: false,
            reason: "path contains antigravity storage".to_string(),
        });
    }
    if path_str.contains(".gemini/") || path_str.contains("/gemini/sessions") {
        return Ok(DetectedAgent {
            slug: "gemini",
            is_override: false,
            reason: "path contains gemini storage".to_string(),
        });
    }

    Err(CliError {
        code: 3,
        kind: CliErrorKind::UnknownAgent.kind_str(),
        message: format!(
            "could not detect the source harness from path '{}'",
            path.display()
        ),
        hint: Some(
            "Pass --agent <name> to override (claude, codex, opencode, pi, omp, gemini, antigravity)."
                .into(),
        ),
        retryable: false,
    })
}

/// Extract a UUID-ish identifier from a session filename.
///
/// Strips a single trailing extension (`.jsonl`, `.json`, `.log`, …)
/// and returns the remaining file stem. For Claude Code and Codex this
/// IS the session UUID. Returns `None` if the path has no file stem.
pub(crate) fn extract_filename_session_id(path: &Path) -> Option<String> {
    path.file_stem()
        .and_then(|s| s.to_str())
        .map(|s| s.to_string())
        .filter(|s| !s.is_empty())
}

/// Best-effort check that `candidate` looks like a UUID in the canonical
/// 8-4-4-4-12 hex form (case-insensitive). Both Claude Code and Codex
/// store sessions at `<dir>/<uuid>.jsonl`, so if we extracted something
/// that clearly isn't a UUID we can surface a clearer error than the
/// "session not found" the downstream harness would emit.
pub(crate) fn looks_like_session_uuid(candidate: &str) -> bool {
    looks_like_session_uuid_bytes(candidate.as_bytes())
}

/// Byte-level core of [`looks_like_session_uuid`], reused by
/// [`extract_uuid_from_stem`] so a sliding window can be checked without an
/// intermediate `&str`.
pub(crate) fn looks_like_session_uuid_bytes(bytes: &[u8]) -> bool {
    if bytes.len() != 36 {
        return false;
    }
    for (i, b) in bytes.iter().enumerate() {
        match i {
            8 | 13 | 18 | 23 => {
                if *b != b'-' {
                    return false;
                }
            }
            _ => {
                if !b.is_ascii_hexdigit() {
                    return false;
                }
            }
        }
    }
    true
}

/// Recover a canonical 8-4-4-4-12 hex UUID from a filename stem that may carry
/// a prefix. Codex names rollout sessions
/// `rollout-<ISO timestamp>-<uuid>.jsonl`, so the bare stem is longer than a
/// raw UUID even though the session id Codex resumes by is the trailing UUID
/// (see bead/issue cass#300). Returns the right-most canonical UUID substring —
/// scanning from the end matches the trailing-UUID layout and avoids carving a
/// hex-shaped slice out of the timestamp — or `None` when the stem holds no
/// UUID. Boundary checks reject windows flanked by another hex digit so we
/// never split a longer hex run.
pub(crate) fn extract_uuid_from_stem(stem: &str) -> Option<String> {
    let bytes = stem.as_bytes();
    if bytes.len() < 36 {
        return None;
    }
    for start in (0..=bytes.len() - 36).rev() {
        let window = &bytes[start..start + 36];
        if !looks_like_session_uuid_bytes(window) {
            continue;
        }
        let left_ok = start
            .checked_sub(1)
            .is_none_or(|p| !bytes[p].is_ascii_hexdigit());
        let right_ok = bytes.get(start + 36).is_none_or(|b| !b.is_ascii_hexdigit());
        if left_ok && right_ok {
            // The window passed the hex/dash shape check, so it is pure ASCII.
            return std::str::from_utf8(window).ok().map(str::to_string);
        }
    }
    None
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum PiFamilyHarness {
    PiAgent,
    Omp,
}

impl PiFamilyHarness {
    pub(crate) const fn display_name(self) -> &'static str {
        match self {
            Self::PiAgent => "Pi Agent",
            Self::Omp => "Oh My Pi (omp)",
        }
    }

    pub(crate) const fn executable(self) -> &'static str {
        match self {
            Self::PiAgent => "pi",
            Self::Omp => "omp",
        }
    }
}

/// Extract a Pi-family session id from a JSONL session file.
///
/// Pi-family session files begin with a `{"type":"session", ...}` header
/// that contains `id` (and often `sessionId`). We scan up to the first
/// 16 non-empty lines to find it, tolerating blank lines and leading
/// metadata. Streams line-by-line so large session logs do not get
/// read into memory in full.
///
/// A 1 MiB byte budget caps the total read so a pathologically long
/// first line (e.g. a JSONL file with no newlines, or a single megabyte
/// of garbage before the real content) cannot OOM the process. The
/// session header is always well under this budget in practice.
pub(crate) fn extract_pi_family_session_id(
    path: &Path,
    harness: PiFamilyHarness,
) -> CliResult<String> {
    use std::io::{BufRead as _, Read as _};
    const MAX_SCAN_BYTES: u64 = 1024 * 1024; // 1 MiB
    let file = std::fs::File::open(path).map_err(|err| CliError {
        code: 4,
        kind: CliErrorKind::SessionFileUnreadable.kind_str(),
        message: format!(
            "cannot open {} session file {}: {err}",
            harness.display_name(),
            path.display()
        ),
        hint: None,
        retryable: false,
    })?;
    let reader = std::io::BufReader::new(file).take(MAX_SCAN_BYTES);
    let mut scanned = 0usize;
    for line in reader.lines() {
        let line = match line {
            Ok(l) => l,
            Err(err) => {
                // Stop at the first I/O error — the file may have been
                // truncated mid-scan, or we hit the MAX_SCAN_BYTES cap
                // in the middle of a multi-byte UTF-8 sequence. Fall
                // through to the session-id-not-found error path so
                // the user gets a clear diagnostic.
                tracing::debug!(
                    path = %path.display(),
                    error = %err,
                    harness = harness.display_name(),
                    "pi-family resume: stopped reading after line I/O error"
                );
                break;
            }
        };
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }
        scanned += 1;
        if scanned > 16 {
            break;
        }
        let value: serde_json::Value = match serde_json::from_str(trimmed) {
            Ok(v) => v,
            Err(_) => continue,
        };
        let entry_type = value.get("type").and_then(|v| v.as_str()).unwrap_or("");
        if entry_type == "session" {
            // Both identifiers are valid only on the authoritative session
            // header. Message/tool records may also carry a `sessionId`, but
            // accepting one would produce a command for a different session.
            if let Some(id) = value
                .get("sessionId")
                .and_then(|v| v.as_str())
                .map(str::trim)
                .filter(|id| !id.is_empty())
            {
                return Ok(id.to_string());
            }
            if let Some(id) = value
                .get("id")
                .and_then(|v| v.as_str())
                .map(str::trim)
                .filter(|id| !id.is_empty())
            {
                return Ok(id.to_string());
            }
        }
    }
    // Deliberately no filename fallback: pi-agent session ids come from
    // the in-file `{"type":"session","id":"..."}` header, not from the
    // filename. Synthesizing an id from the filename would produce a
    // command that looks plausible but the native harness would reject with
    // a confusing error. Fail explicitly so the user knows what's wrong.
    Err(CliError {
        code: 5,
        kind: CliErrorKind::SessionIdNotFound.kind_str(),
        message: format!(
            "no usable session id found in a session header in {} file {} (scanned first 16 non-empty lines)",
            harness.display_name(),
            path.display()
        ),
        hint: Some(format!(
            "{} session ids live in the `{{\"type\":\"session\",\"id\":\"...\"}}` header of the JSONL file. If the file is missing its header, invoke `{} --resume <id>` directly with the id you want.",
            harness.display_name(),
            harness.executable(),
        )),
        retryable: false,
    })
}

/// Extract an OpenCode session id from a cass-stored source_path.
///
/// Cass records OpenCode conversations with
/// `source_path = <opencode.db>/<url-encoded-session-id>`, so the
/// session id is the URL-decoded final path component and the parent
/// directory's name is `opencode.db`. When `strict` is true (the
/// auto-detection path) we reject anything not matching that shape —
/// otherwise a random file under `~/.config/opencode` (such as
/// `config.json`) would produce a plausible-looking but bogus resume
/// command. When `strict` is false (the `--agent opencode` override)
/// we trust the caller and only enforce the presence of a non-empty
/// final component.
pub(crate) fn extract_opencode_session_id(path: &Path, strict: bool) -> CliResult<String> {
    let raw = path
        .file_name()
        .and_then(|s| s.to_str())
        .ok_or_else(|| CliError {
            code: 5,
            kind: CliErrorKind::SessionIdNotFound.kind_str(),
            message: format!("opencode path has no final component: {}", path.display()),
            hint: None,
            retryable: false,
        })?;
    if strict {
        // The parent directory must be the opencode.db virtual folder.
        // `parent_name` is the last segment of the parent path (already
        // split by the OS), so a simple equality check is both
        // sufficient and correct — no need to worry about slashes.
        let parent_name = path
            .parent()
            .and_then(|p| p.file_name())
            .and_then(|n| n.to_str());
        let looks_like_session_path = parent_name == Some("opencode.db");
        if !looks_like_session_path {
            return Err(CliError {
                code: 5,
                kind: CliErrorKind::SessionIdNotFound.kind_str(),
                message: format!(
                    "opencode session path must live under an 'opencode.db' directory, got: {}",
                    path.display()
                ),
                hint: Some(
                    "Expected path shape: '<.../opencode.db>/<session-id>' (as emitted by `cass search` and `cass sessions`). Pass `--agent opencode` to bypass this check if the id is correct."
                        .into(),
                ),
                retryable: false,
            });
        }
    }
    // Percent-decode the component. urlencoding::decode returns the
    // original string on pass-through, so this is always non-lossy.
    let decoded = urlencoding::decode(raw)
        .map(std::borrow::Cow::into_owned)
        .unwrap_or_else(|_| raw.to_string());
    if decoded.is_empty() || decoded == "opencode.db" {
        return Err(CliError {
            code: 5,
            kind: CliErrorKind::SessionIdNotFound.kind_str(),
            message: format!(
                "could not extract opencode session id from '{}'",
                path.display()
            ),
            hint: Some(
                "Expected path shape: '<opencode.db>/<session-id>' (as emitted by cass search)."
                    .into(),
            ),
            retryable: false,
        });
    }
    Ok(decoded)
}

/// Extract the Antigravity conversation UUID from a transcript source path.
///
/// Antigravity records each conversation under
/// `<...>/antigravity{,-cli}/brain/<uuid>/.system_generated/logs/transcript.jsonl`
/// (a `transcript_full.jsonl` sibling may also appear). The `<uuid>` — the same
/// id `agy --conversation <uuid>` resumes by — is the name of the directory that contains
/// `.system_generated`. We locate that segment structurally rather than by a
/// fixed depth so extraction still works when a remote mirror adds leading path
/// components, and fall back to the component immediately after a `brain`
/// segment when the path points straight at the conversation directory.
pub(crate) fn extract_antigravity_conversation_id(path: &Path) -> CliResult<String> {
    // Primary: the directory whose immediate child is `.system_generated`.
    let mut cursor = path;
    while let Some(parent) = cursor.parent() {
        if parent.file_name().is_some_and(|n| n == ".system_generated")
            && let Some(uuid) = parent
                .parent()
                .and_then(Path::file_name)
                .and_then(|n| n.to_str())
                .map(str::trim)
                .filter(|s| !s.is_empty())
        {
            return Ok(uuid.to_string());
        }
        cursor = parent;
    }
    // Fallback: the path component right after a `brain` segment is the <uuid>
    // (covers a path that already points at `brain/<uuid>` or below).
    let names: Vec<&str> = path
        .components()
        .filter_map(|c| c.as_os_str().to_str())
        .collect();
    if let Some(pos) = names.iter().position(|n| *n == "brain")
        && let Some(uuid) = names
            .get(pos + 1)
            .map(|s| s.trim())
            .filter(|s| !s.is_empty())
    {
        return Ok(uuid.to_string());
    }
    Err(CliError {
        code: 5,
        kind: CliErrorKind::SessionIdNotFound.kind_str(),
        message: format!(
            "cannot derive Antigravity conversation id from '{}'",
            path.display()
        ),
        hint: Some(
            "Expected an Antigravity transcript path like '<...>/antigravity/brain/<uuid>/.system_generated/logs/transcript.jsonl' (IDE) or '<...>/antigravity-cli/brain/<uuid>/...' (agy CLI)."
                .into(),
        ),
        retryable: false,
    })
}

/// Build the ready-to-run resume target for a session path. Does not
/// touch the filesystem unless the agent requires file-based id
/// extraction (pi-agent).
pub(crate) fn resolve_resume_target(
    path: &Path,
    agent_override: Option<&str>,
) -> CliResult<ResumeTarget> {
    let detected = detect_resume_agent(path, agent_override)?;
    let detection_reason = detected.reason;
    // Skip strict validations (like UUID-shape checks) when the user
    // passed `--agent ...` — explicit is explicit. We only enforce
    // strict format rules when detection came from path inference,
    // because that's the case where cass can meaningfully help the
    // user catch a "wrong path" mistake.
    let is_override = detected.is_override;

    match detected.slug {
        "claude" => {
            let uuid = extract_filename_session_id(path).ok_or_else(|| CliError {
                code: 5,
                kind: CliErrorKind::SessionIdNotFound.kind_str(),
                message: format!(
                    "cannot derive Claude Code session UUID from '{}'",
                    path.display()
                ),
                hint: None,
                retryable: false,
            })?;
            if !is_override && !looks_like_session_uuid(&uuid) {
                return Err(CliError {
                    code: 5,
                    kind: CliErrorKind::SessionIdNotFound.kind_str(),
                    message: format!(
                        "filename stem '{uuid}' does not look like a Claude Code session UUID (expected 8-4-4-4-12 hex)"
                    ),
                    hint: Some(
                        "Did you pass a project directory or notes file instead of a <uuid>.jsonl session file? Pass `--agent claude` to bypass this check if the id is correct."
                            .into(),
                    ),
                    retryable: false,
                });
            }
            Ok(ResumeTarget {
                agent: "claude",
                argv: vec!["claude".into(), "--resume".into(), uuid.clone()],
                session_id: Some(uuid),
                detection_reason,
            })
        }
        "codex" => {
            let stem = extract_filename_session_id(path).ok_or_else(|| CliError {
                code: 5,
                kind: CliErrorKind::SessionIdNotFound.kind_str(),
                message: format!("cannot derive Codex session UUID from '{}'", path.display()),
                hint: None,
                retryable: false,
            })?;
            // Codex rollout files are named `rollout-<timestamp>-<uuid>.jsonl`,
            // so the bare stem can carry a prefix. The id Codex resumes by is
            // the trailing UUID — recover it from the stem (falling back to the
            // stem itself when no UUID is present), so both auto-detected and
            // `--agent codex` invocations hand `codex resume` the canonical id
            // rather than the full filename (cass#300).
            let uuid = if looks_like_session_uuid(&stem) {
                stem.clone()
            } else {
                extract_uuid_from_stem(&stem).unwrap_or_else(|| stem.clone())
            };
            if !is_override && !looks_like_session_uuid(&uuid) {
                return Err(CliError {
                    code: 5,
                    kind: CliErrorKind::SessionIdNotFound.kind_str(),
                    message: format!(
                        "filename stem '{stem}' does not look like a Codex session UUID (expected 8-4-4-4-12 hex)"
                    ),
                    hint: Some(
                        "Did you pass a date directory or log file instead of a <uuid>.jsonl session file? Pass `--agent codex` to bypass this check if the id is correct."
                            .into(),
                    ),
                    retryable: false,
                });
            }
            Ok(ResumeTarget {
                agent: "codex",
                argv: vec!["codex".into(), "resume".into(), uuid.clone()],
                session_id: Some(uuid),
                detection_reason,
            })
        }
        "opencode" => {
            // Strict mode only when we auto-detected. An explicit
            // `--agent opencode` bypasses the parent-directory check.
            let id = extract_opencode_session_id(path, !is_override)?;
            // Current OpenCode (1.16.x) continues a session via the
            // top-level `--session <id>` flag (`-s` for short); the old
            // `opencode resume <id>` subcommand was removed and is no
            // longer discoverable via `--help` (cass#316). Emit the
            // documented flag form so the generated command actually
            // resumes on a current OpenCode install.
            Ok(ResumeTarget {
                agent: "opencode",
                argv: vec!["opencode".into(), "--session".into(), id.clone()],
                session_id: Some(id),
                detection_reason,
            })
        }
        "pi_agent" => {
            let id = extract_pi_family_session_id(path, PiFamilyHarness::PiAgent)?;
            Ok(ResumeTarget {
                agent: "pi_agent",
                argv: vec!["pi".into(), "--resume".into(), id.clone()],
                session_id: Some(id),
                detection_reason,
            })
        }
        "omp" => {
            let id = extract_pi_family_session_id(path, PiFamilyHarness::Omp)?;
            let mut argv = vec!["omp".to_string()];
            let profile = crate::connectors::omp::resume_profile_from_path(path);
            if let Some(profile) = profile {
                argv.extend(["--profile".to_string(), profile]);
            }
            if let Some(session_dir) = omp_session_dir_from_path(path) {
                argv.extend([
                    "--session-dir".to_string(),
                    session_dir.display().to_string(),
                ]);
            }
            argv.extend(["--resume".to_string(), id.clone()]);
            Ok(ResumeTarget {
                agent: "omp",
                argv,
                session_id: Some(id),
                detection_reason,
            })
        }
        "gemini" => {
            // Gemini resumes by path rather than by id. Use the
            // absolute path to avoid cwd ambiguity when `cass resume`
            // is piped through another process. dunce keeps Windows' \\?\
            // verbatim prefix out of the argv handed to gemini.
            let canonical = dunce::canonicalize(path).unwrap_or_else(|_| path.to_path_buf());
            let path_str = canonical.display().to_string();
            Ok(ResumeTarget {
                agent: "gemini",
                argv: vec![
                    "gemini".into(),
                    "session".into(),
                    "restore".into(),
                    path_str,
                ],
                session_id: None,
                detection_reason,
            })
        }
        "antigravity" => {
            // Antigravity resumes by conversation UUID: `agy --conversation
            // <uuid>` (verified against agy 1.0.x `--help`: "--conversation
            // Resume a previous conversation by ID"). The UUID is the
            // `brain/<uuid>` directory name, recoverable from the transcript
            // source path cass stores — the same id the connector keys both
            // `conversations/<uuid>.db` and `brain/<uuid>/` by, and the
            // normalized `external_id` (cass#314).
            let uuid = extract_antigravity_conversation_id(path)?;
            Ok(ResumeTarget {
                agent: "antigravity",
                argv: vec!["agy".into(), "--conversation".into(), uuid.clone()],
                session_id: Some(uuid),
                detection_reason,
            })
        }
        // Unreachable: detect_resume_agent validates the slug.
        other => Err(CliError {
            code: 3,
            kind: CliErrorKind::UnknownAgent.kind_str(),
            message: format!("internal: unhandled agent slug '{other}'"),
            hint: None,
            retryable: false,
        }),
    }
}
